def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if len(alive) == 0:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.8
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    cindy_prev = None
    pressure = 0.0
    desperate_count = 0

    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) > pressure:
                pressure = float(bid)
        if agent_id == 'Cindy' and bid is not None:
            cindy_prev = float(bid)
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1

    scarcity = 1.0
    if supply <= 16:
        scarcity = 1.25
    elif supply <= 19:
        scarcity = 1.1
    elif supply >= 24:
        scarcity = 0.85
    elif supply >= 22:
        scarcity = 0.92

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.45
    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days == 1:
        urgency += 0.35

    if cindy_prev is None:
        target = DAILY_SALARY * 0.55 * scarcity
        if urgency > 0.8:
            target = DAILY_SALARY * 0.95
        elif desperate_count >= 2:
            target = DAILY_SALARY * 0.7 * scarcity
    else:
        if urgency >= 1.0:
            target = min(budget, cindy_prev + 8.0)
        elif urgency > 0.0:
            target = max(DAILY_SALARY * 0.6, cindy_prev * 0.72 * scarcity)
        else:
            if cindy_prev >= 160:
                target = DAILY_SALARY * 0.28 * scarcity
            elif cindy_prev >= 120:
                target = DAILY_SALARY * 0.38 * scarcity
            elif cindy_prev >= 80:
                target = DAILY_SALARY * 0.52 * scarcity
            else:
                target = max(DAILY_SALARY * 0.45, cindy_prev + 2.0)

    if day >= 8 and hp > 4 and no_water_days == 0:
        target *= 0.9

    reserve_floor = 0.0
    days_left = max(0, 10 - int(day))
    if days_left > 0 and hp > 2:
        reserve_floor = min(budget * 0.5, days_left * DAILY_SALARY * 0.18)

    bid = min(budget, target)
    if budget - bid < reserve_floor and urgency < 1.0:
        bid = max(0.0, budget - reserve_floor)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.92))
    elif hp <= 4 or no_water_days == 1:
        bid = max(bid, min(budget, DAILY_SALARY * 0.62 * scarcity))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no one alive, bid conservatively
    if not alive_opps:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    # Use only yesterday previous_trace for immediate reaction
    prev_bids = []
    for oid, o in alive_opps:
        pt = o.get('previous_trace', {})
        if pt and pt.get('bid') is not None:
            try:
                prev_bids.append(float(pt.get('bid', 0.0)))
            except Exception:
                pass

    # Compute perceived pressure from Cindy specifically if present
    cindy = opponents_status.get('Cindy', None)
    cindy_prev_bid = None
    if cindy is not None and cindy.get('alive', False):
        pt = cindy.get('previous_trace', {})
        if pt and pt.get('bid') is not None:
            try:
                cindy_prev_bid = float(pt.get('bid'))
            except Exception:
                cindy_prev_bid = None

    # Determine target spend based on supply and pressure
    # Higher supply reduces need to overbid.
    supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_factor = max(0.0, min(1.0, supply_factor))

    # Baseline: try to buy enough to avoid water starvation
    # Assume each day needs WATER_REQ and water allocation is proportional to bid.
    # We translate this into a bid fraction of DAILY_SALARY.
    base_bid = DAILY_SALARY * (0.55 - 0.15 * supply_factor)  # 0.55..0.40

    # Pressure escalation if Cindy was bidding aggressively
    # If Cindy maxed out yesterday (~>=150), treat as strong threat.
    if cindy_prev_bid is not None:
        if cindy_prev_bid >= 170:
            pressure_bid = DAILY_SALARY * 0.95
        elif cindy_prev_bid >= 140:
            pressure_bid = DAILY_SALARY * 0.75
        elif cindy_prev_bid >= 100:
            pressure_bid = DAILY_SALARY * 0.62
        else:
            pressure_bid = DAILY_SALARY * 0.55
    else:
        # Fallback: use max of previous bids among alive
        if prev_bids:
            highest_prev_bid = max(prev_bids)
            if highest_prev_bid >= 170:
                pressure_bid = DAILY_SALARY * 0.95
            elif highest_prev_bid >= 140:
                pressure_bid = DAILY_SALARY * 0.75
            elif highest_prev_bid >= 100:
                pressure_bid = DAILY_SALARY * 0.62
            else:
                pressure_bid = DAILY_SALARY * 0.55
        else:
            pressure_bid = DAILY_SALARY * 0.55

    # Health urgency: if low hp or many no-water days, increase bid.
    hp = float(my_status.get('hp', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    urgency_multiplier = 1.0
    if hp <= 2:
        urgency_multiplier = 1.15
    elif hp <= 4:
        urgency_multiplier = 1.07

    if no_water_days >= 2:
        urgency_multiplier = max(urgency_multiplier, 1.15)
    if no_water_days >= 4:
        urgency_multiplier = max(urgency_multiplier, 1.25)

    # Final bid: blend base and pressure; avoid overspending
    desired = (0.45 * base_bid) + (0.55 * pressure_bid)
    desired *= urgency_multiplier

    budget = float(my_status.get('budget', 0.0))

    # Clamp to budget and to a reasonable upper bound
    upper = min(budget, DAILY_SALARY * 1.1)  # don't exceed ~99 salary per day
    lower = 0.0

    bid = max(lower, min(upper, desired))

    # If budget is tiny, still bid what we can
    if budget <= 1e-6:
        return 0.0

    # Ensure bid is not negative and is float
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    previous_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace')
        if prev and prev.get('bid') is not None:
            previous_bids.append(prev['bid'])
    max_prev = max(previous_bids) if previous_bids else 0
    epsilon = 1.5
    base_bid = min(my_status['budget'], max(DAILY_SALARY * 0.4, max_prev + epsilon))
    if my_status['hp'] <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)
    supply = day_context['supply']
    num_players = len(alive_opponents) + 1
    total_needed = num_players * WATER_REQ
    if supply < total_needed:
        base_bid = max(base_bid, DAILY_SALARY * 0.7)
    if my_status['no_water_days'] >= 1:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    bid = min(base_bid, my_status['budget'])
    return max(0, bid)
